insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"EITHER_GTE_8","title":"¿Algún equipo llegará a 8 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"either_gte","n":8},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"EITHER_GTE_9","title":"¿Algún equipo anotará 9 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"either_gte","n":9},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"EITHER_GTE_10","title":"¿Algún equipo llegará a 10 carreras?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"either_gte","n":10},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"SHUTOUT","title":"¿Algún equipo terminará en cero?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"shutout"},"priority":0,"cooldown":2,"tags":["defensiva"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;